@Configuration
public class DatabaseMigrationConfig {
    // Spring Boot auto-configuration handles Flyway/Liquibase initialization ordering automatically.
    // However, if manual validation or custom callbacks are required, you can hook into the beans:

    @Bean
    public FlywayMigrationStrategy cleanMigrateStrategy() {
        return flyway -> {
            // Custom pre-migration checks or telemetry can be injected here
            flyway.migrate();
        };
    }
}
